<script lang="ts">
  let {values=$bindable(),capabilities,disabled=false,error='',onReset}:{values:import('./speech-controls.js').SpeechControlValues;capabilities:import('./speech-controls.js').SpeechCapabilities;disabled?:boolean;error?:string;onReset:()=>void}=$props();
</script>
<details class="speech-controls">
  <summary>Advanced controls <span>{[capabilities.speed?'Speed':'',capabilities.temperature?'Temperature':'',capabilities.sentencePause?'Timing':'','Variation'].filter(Boolean).join(' · ')}</span></summary>
  <fieldset {disabled} aria-label="Advanced speech controls">
    {#if capabilities.speed}<div class="control"><label for="speech-speed">Speaking speed</label><input id="speech-speed" type="number" min="0.5" max="2" step="0.05" bind:value={values.speed} disabled={!!capabilities.duration&&values.useDuration} aria-describedby="speech-speed-help"/><p id="speech-speed-help">1× is normal. Lower is slower; higher is faster.</p></div>{/if}
    {#if capabilities.temperature}<div class="control"><label for="speech-temperature">Temperature</label><input id="speech-temperature" type="number" min={capabilities.temperatureMin??0.1} max="1" step="0.05" bind:value={values.temperature} aria-describedby="speech-temperature-help"/><p id="speech-temperature-help">Lower is steadier; higher adds variation. Default: {capabilities.defaultTemperature??0.3}.</p></div>{/if}
    {#if capabilities.sentencePause}<div class="control"><label for="speech-pause">Sentence pause (seconds)</label><input id="speech-pause" type="number" min="0" max="2" step="0.05" bind:value={values.sentencePause} disabled={!!capabilities.duration&&values.useDuration} aria-describedby="speech-pause-help"/><p id="speech-pause-help">Silence added between sentences. Default: {capabilities.defaultSentencePause??0.2} seconds.</p></div>{/if}
    {#if capabilities.numSteps}<div class="control"><label for="speech-steps">Generation steps</label><select id="speech-steps" bind:value={values.numSteps}><option value={16}>16 · Fast</option><option value={32}>32 · Standard</option><option value={64}>64 · More detailed</option></select><p>More steps take longer. Default: {capabilities.defaultNumSteps??32}.</p></div>{/if}
    {#if capabilities.duration}<div class="duration control"><label class="variation-choice"><input type="checkbox" bind:checked={values.useDuration}/>Set a target duration</label><p>Optional approximate length for the whole script. This replaces speed and sentence-pause settings.</p>{#if values.useDuration}<label for="speech-duration">Target duration (seconds)</label><input id="speech-duration" type="number" min="0.5" max="600" step="0.1" bind:value={values.duration}/>{/if}</div>
    {:else if capabilities.temperature&&!capabilities.speed}<p class="control-note">Speaking speed and target duration are not supported by this voice. You can adjust the pauses between sentences.</p>{/if}
    <div class="variation control"><label class="variation-choice"><input type="checkbox" bind:checked={values.automaticSeed}/>New variation each time</label><p>Turn this off to compare takes using a fixed seed on this computer.</p>{#if !values.automaticSeed}<label for="speech-seed">Variation seed</label><input id="speech-seed" type="number" min="0" max="4294967295" step="1" bind:value={values.seed}/>{/if}</div>
    <div class="controls-footer"><span>Applied settings are saved with each recording.</span><button class="secondary" onclick={onReset}>Reset defaults</button></div>
  </fieldset>
  {#if error}<p class="controls-error" role="alert">{error}</p>{/if}
</details>
<style>
  .speech-controls{font-size:12px;border-bottom:1px solid var(--studio-divider)}summary{cursor:pointer;padding:13px 0;color:var(--studio-text);font-weight:500}summary span{font-size:10px;color:var(--studio-muted);font-weight:400;margin-left:8px}fieldset{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;border:0;margin:0;padding:8px 0 18px;min-width:0}.control{min-width:0}label{display:block;font-size:11px;font-weight:500;color:var(--studio-text);margin:0 0 9px}input[type=number],select{display:block;width:100%;max-width:150px;box-sizing:border-box;border:1px solid var(--studio-border);border-radius:8px;padding:9px 11px;font:inherit;font-size:12px;background:var(--studio-page);color:var(--studio-text)}p{font-size:10px;line-height:1.7;color:var(--studio-muted);margin:9px 0 0}.variation,.duration,.control-note{grid-column:1/-1}.variation-choice{display:flex;align-items:center;gap:8px;font-weight:400;margin-bottom:0}.variation-choice input{width:16px;height:16px;margin:0;accent-color:var(--studio-accent)}.variation>label[for],.duration>label[for]{margin-top:12px}.controls-footer{grid-column:1/-1;display:flex;justify-content:space-between;align-items:center;gap:12px;color:var(--studio-muted);font-size:10px;flex-wrap:wrap}.controls-footer button{font-size:10px;padding:7px 11px}input:focus-visible{outline:2px solid var(--studio-focus);outline-offset:2px}fieldset:disabled{opacity:.65}.controls-error{color:var(--studio-tone-ffb2be);margin:0 0 12px}@media(max-width:700px){fieldset{grid-template-columns:minmax(0,1fr)}summary span{display:block;margin:5px 0 0 15px}}
</style>
